        if (ACLStringHasSpaces(argv[1], sdslen(argv[1]))) {
            errors = sdscatprintf(errors, "'%s:%d: username '%s' contains invalid characters. ", server.acl_filename,
                                  linenum, argv[1]);
            sdsfreesplitres(argv, argc);
            continue;
        }

